    use serde_json::{Value, from_str, to_string, Map, json};
    use std::io::{self, Read};

    fn network_topology_analyzer(input: serde_json::Value) -> serde_json::Value {
    use serde_json::{json, Value};

    let nodes = match &input["nodes"] {
        Value::Array(arr) => arr.clone(),
        _ => return json!({"error": "Invalid nodes structure"}),
    };

    let connections = match &input["connections"] {
        Value::Array(arr) => arr.clone(),
        _ => return json!({"error": "Invalid connections structure"}),
    };

    let traversal_mode = input["mode"].as_str().unwrap_or("default");

    let mut node_scores = Vec::new();

    // First pass: Initialize node scores
    for (i, node) in nodes.iter().enumerate() {
        let node_id = match &node["id"] {
            Value::String(s) => s.clone(),
            Value::Number(n) => n.to_string(),
            _ => i.to_string(),
        };

        let node_type = match &node["type"] {
            Value::String(s) => s.clone(),
            _ => "generic".to_string(),
        };

        // Score calculation
        let base_score = (i as i32 * 7 + 3) % 100;
        let type_modifier = match node_type.as_str() {
            "router" => 15,
            "switch" => 10,
            "server" => 20,
            "client" => 5,
            _ => 0,
        };

        let initial_score = (base_score + type_modifier) & 0x7F;

        node_scores.push(json!({
            "id": node_id,
            "score": initial_score,
            "processed": false,
            "visited": 0,
        }));
    }

    // Multiple iterations to make it harder to follow
    for iteration in 0..3 {
        for connection in &connections {
            let source = match &connection["source"] {
                Value::String(s) => s.clone(),
                Value::Number(n) => n.to_string(),
                _ => continue,
            };

            let target = match &connection["target"] {
                Value::String(s) => s.clone(),
                Value::Number(n) => n.to_string(),
                _ => continue,
            };

            let weight = match &connection["weight"] {
                Value::Number(n) => n.as_i64().unwrap_or(1) as i32,
                _ => 1,
            };

            // Find source and target indexes
            let source_idx = node_scores.iter().position(|node| 
                node["id"].as_str().unwrap_or("") == source
            );

            let target_idx = node_scores.iter().position(|node| 
                node["id"].as_str().unwrap_or("") == target
            );

            if let (Some(s_idx), Some(t_idx)) = (source_idx, target_idx) {
                let source_score = node_scores[s_idx]["score"].as_i64().unwrap_or(0) as i32;
                let target_score = node_scores[t_idx]["score"].as_i64().unwrap_or(0) as i32;

                // Complex transfer logic based on mode
                let transfer = match traversal_mode {
                    "priority" => ((source_score & 0x0F) | (weight << 2)) % 30,
                    "balanced" => ((source_score / 2) + weight) % 25,
                    "cascade" => (source_score * weight) % 20,
                    _ => ((source_score + weight) / 2) % 15,
                };

                // Update scores with operation based on iteration
                let new_target_score = match iteration {
                    0 => target_score + transfer,
                    1 => (target_score + transfer) ^ (s_idx as i32 * 3),
                    _ => (target_score + transfer) | ((s_idx as i32) << 1),
                };

                let new_source_score = match iteration {
                    0 => source_score - (transfer / 2),
                    1 => (source_score - (transfer / 2)) | (t_idx as i32),
                    _ => (source_score - (transfer / 2)) ^ ((t_idx as i32) << 2),
                };

                // Update scores with clamping
                node_scores[s_idx]["score"] = json!(new_source_score.max(0).min(127));
                node_scores[t_idx]["score"] = json!(new_target_score.max(0).min(127));

                node_scores[s_idx]["processed"] = json!(true);
                node_scores[t_idx]["processed"] = json!(true);

                let visits = node_scores[t_idx]["visited"].as_i64().unwrap_or(0) as i32;
                node_scores[t_idx]["visited"] = json!(visits + 1);
            }
        }
    }

    // Calculate centrality
    let mut centrality_values = Vec::new();
    for (i, node) in node_scores.iter().enumerate() {
        let score = node["score"].as_i64().unwrap_or(0) as i32;
        let visits = node["visited"].as_i64().unwrap_or(0) as i32;
        let processed = node["processed"].as_bool().unwrap_or(false);

        let centrality = if processed {
            ((score * 3 + visits * 5) ^ (i as i32)) % 100
        } else {
            ((score / 2) | (visits << 2)) % 50
        };

        centrality_values.push(json!({
            "id": node["id"].clone(),
            "centrality": centrality,
            "tier": match centrality {
                0..=20 => "low",
                21..=50 => "medium",
                51..=80 => "high",
                _ => "critical",
            }
        }));
    }

    // Calculate network metrics
    let mut total_centrality = 0;
    let mut critical_nodes = 0;
    let mut tier_counts = json!({
        "low": 0,
        "medium": 0,
        "high": 0,
        "critical": 0
    });

    for node in &centrality_values {
        let centrality = node["centrality"].as_i64().unwrap_or(0) as i32;
        total_centrality += centrality;

        let tier = node["tier"].as_str().unwrap_or("low");
        if tier == "critical" {
            critical_nodes += 1;
        }

        // Update tier counts
        if let Some(count) = tier_counts[tier].as_i64() {
            tier_counts[tier] = json!(count + 1);
        }
    }

    // Calculate network stability
    let stability_factor = if nodes.len() > 0 {
        let avg_centrality = total_centrality / nodes.len() as i32;
        let stability = 100 - ((avg_centrality * critical_nodes) % 100);
        stability.max(0).min(100)
    } else {
        0
    };

    // Return the analysis results
    json!({
        "node_analysis": centrality_values,
        "network_metrics": {
            "stability": stability_factor,
            "tier_distribution": tier_counts,
            "critical_node_count": critical_nodes
        }
    })
}

    fn main() {
        let mut buf = String::new();
        io::stdin().read_to_string(&mut buf).unwrap();
        let inp: Value = from_str(&buf).unwrap();
        let out = network_topology_analyzer(inp);
        println!("{}", to_string(&out).unwrap());
    }

