from typing import List, Union

def process_sequence(seq: str) -> Union[List[int], str]:
    """Processes a comma-separated sequence of numbers."""
    try:
        nums = [int(x) for x in seq.split(',')]
        if len(nums) % 2 != 0:
            return 'Number of elements should be even. Exit'
        return nums
    except ValueError:
        return 'Value is not a number. Exit'
```

