                k_val = process_element(k, depth + 1)
                v_val = process_element(v, depth + 1)
                # Logical implication: if k then v is equivalent to (not k) or v
                impl = (1 - truth_value(k_val)) | truth_value(v_val)
                result = (result * 7 + k_val * 3 + v_val * 5 + impl * 11) % 10000
        elif isinstance(elem, list):
