                result = 0
            else:
                values = [process_element(x, depth + 1) for x in elem[:16]]
                # Apply contraposition: not(if a then b) = a and not b
                contrapos = 0
                for i in range(len(values) - 1):
                    a, b = truth_value(values[i]), truth_value(values[i + 1])
                    contrapos = (contrapos * 5 + (a & (1 - b)) * 17) % 10000
                result = contrapos + sum(values) % 997
        elif isinstance(elem, str):
