        # Digital root calculation
        dr = 0
        temp = abs(n)
        while temp > 0:
            dr += temp % 10
            temp //= 10
        while dr >= 10:
            temp = dr
            dr = 0
            while temp > 0:
                dr += temp % 10
                temp //= 10

        # Final transformation
