import ast
import operator

def calculate(expression):
    """Safely evaluates a mathematical expression."""

    ops = {ast.Add: operator.add, ast.Sub: operator.sub,
           ast.Mult: operator.mul, ast.Div: operator.truediv}

    def eval_expr(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            op = ops[type(node.op)]
            return op(eval_expr(node.left), eval_expr(node.right))
        elif isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.USub):
                return -eval_expr(node.operand)
            else:
                raise ValueError("Unsupported unary operator")
        else:
            raise ValueError("Unsupported node type")

    return eval_expr(ast.parse(expression, mode='eval').body)

if __name__ == "__main__":
    expression = input()
    result = calculate(expression)
    print(result)
```

This program utilizes the `ast` module to parse the input expression into an Abstract Syntax Tree.  A recursive function `eval_expr` then traverses this tree, applying the appropriate arithmetic operations based on the node types encountered, ensuring a secure and controlled evaluation process. Numerical values are returned directly, while binary operations trigger the corresponding mathematical function.

