    def encode_string(s, shift=0):
        result = ""
        for i, char in enumerate(s):
            if char.isalpha():
                base = ord('A') if char.isupper() else ord('a')
                offset = (ord(char) - base + i + shift) % 26
                result += chr(base + offset)
            elif char.isdigit():
                result += str((int(char) * 3 + shift) % 10)
            else:
                result += char
        return result

