        if isinstance(item, dict):
            key_types = {}
            for k in item.keys():
                t = type(k).__name__
                key_types[t] = key_types.get(t, 0) + 1

            value_complexity = sum(1 for v in item.values() if isinstance(v, (dict, list)))

            return {
                "structure": "dictionary",
                "size": len(item),
                "key_types": key_types,
                "complexity": value_complexity
            }

        elif isinstance(item, list):
            types_count = {}
            for x in item:
                t = type(x).__name__
                types_count[t] = types_count.get(t, 0) + 1

            return {
                "structure": "list",
                "length": len(item),
                "types": types_count,
                "is_homogeneous": len(types_count) <= 1
            }

        else:
            return {
                "structure": "primitive",
                "type": type(item).__name__
            }

    result = {
        "transformed": process_element(data),
        "metadata": analyze_structure(data),
        "checksum": calculate_checksum(data)
    }

    return result

def calculate_checksum(data):
