def cholesky_factorization(matrix: List[List[float]]) -> List[List[float]]:
    n = len(matrix)
    lower_triangular = [[0.0] * n for _ in range(n)]

    for i in range(n):
        for j in range(i + 1):
            sum_val = sum(lower_triangular[i][k] * lower_triangular[j][k] for k in range(j))

            if i == j:
                lower_triangular[i][i] = (matrix[i][i] - sum_val)**0.5
            else:
                lower_triangular[i][j] = (matrix[i][j] - sum_val) / lower_triangular[j][j]

    return lower_triangular
```

