import java.util.Arrays;

class Solution {
    /**
     * Converts a 2D array of integers into a 1D array.
     *
     * @param twoDArray The non-empty 2D array to convert.
     * @return A 1D array containing all elements from the 2D array.
     */
    public int[] convertTo1D(int[][] twoDArray) {
        int rows = twoDArray.length;
        int cols = twoDArray[0].length;
        int[] oneDArray = new int[rows * cols];
        int index = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                oneDArray[index++] = twoDArray[i][j];
            }
        }

        return oneDArray;
    }

    public static void main(String[] args) {
        Solution solution = new Solution();

        int[][] array1 = {{1, 2}, {3, 4}};
        int[] result1 = solution.convertTo1D(array1);
        System.out.println("Test 1: " + Arrays.toString(result1)); // Expected: [1, 2, 3, 4]

        int[][] array2 = {{1}, {2}, {3}};
        int[] result2 = solution.convertTo1D(array2);
        System.out.println("Test 2: " + Arrays.toString(result2)); // Expected: [1, 2, 3]

        int[][] array3 = {{1, 2, 3}, {4, 5, 6}};
        int[] result3 = solution.convertTo1D(array3);
        System.out.println("Test 3: " + Arrays.toString(result3)); // Expected: [1, 2, 3, 4, 5, 6]
    }
}
