```js
export function processData(input){
  const contacts = Array.isArray(input.contacts)?input.contacts:[];
  const n = contacts.length;
  const parent = Array.from({length:n},(_,i)=>i);
  function find(i){return parent[i]===i?i:(parent[i]=find(parent[i]));}
  function union(a,b){const ra=find(a),rb=find(b);if(ra!==rb)parent[rb]=ra;}
  function norm(s){return typeof s==='string'?s.toLowerCase().replace(/\s+/g,''):'';}
  for(let i=0;i<n;i++)for(let j=i+1;j<n;j++){
    const a=contacts[i],b=contacts[j];
    if(norm(a.name)&&norm(a.name)===norm(b.name))union(i,j);
    else if(norm(a.email)===norm(b.email)&&norm(a.email))union(i,j);
    else if(a.phone&&b.phone&&a.phone===b.phone)union(i,j);
  }
  const groups = {};
  for(let i=0;i<n;i++){const r=find(i);groups[r]=groups[r]||[];groups[r].push(contacts[i]);}
  const mergedContacts = Object.values(groups).map(group=>{
    const m = {};
    for(const c of group)for(const k in c){
      const v=c[k];
      if(v==null)continue;
      if(m[k]==null)m[k]=v;
      else if(typeof v==='string'&&v.length>String(m[k]).length)m[k]=v;
    }
    return m;
  });
  const flights = Array.isArray(input.flights)?input.flights:[];
  flights.sort((a,b)=>a.arrival-b.arrival);
  const gates = [];
  const assigned = flights.map(f=>{
    let g = gates.findIndex(end=>end<=f.arrival);
    if(g<0){g=gates.length;gates.push(f.departure);}else gates[g]=f.departure;
    return {id:f.id,gate:g+1};
  });
  return {contacts:mergedContacts,flights:assigned};
}
