Return the output dict as a json inside a json with the key 'code_output'. Here is the code:

```python
def evaluate_candidates(data):
    # Initialize output structure
    results = {"ranked_candidates": [], "recommendations": [], "department_matches": {}}

    # Extract candidates from input
    candidates = data.get("candidates", []) if isinstance(data, dict) else data
    if not candidates and isinstance(data, dict) and "name" in data:
        candidates = [data]

    # Default skill weights if not provided
    skill_weights = data.get("skill_weights", {
        "technical": 5, "experience": 4, "education": 3, 
        "communication": 3, "leadership": 2
    }) if isinstance(data, dict) else {
        "technical": 5, "experience": 4, "education": 3, 
        "communication": 3, "leadership": 2
    }

    # Process each candidate (max 16)
    scored_candidates = []
    for idx, candidate in enumerate(candidates[:16]):
        scores = {}

        # Technical skills scoring
        skills = candidate.get("skills", [])
        if isinstance(skills, list):
            tech_score = 0
            for i, skill in enumerate(skills[:10]):
                level = skill.get("level", 1) if isinstance(skill, dict) else 1
                name = skill.get("name", "") if isinstance(skill, dict) else str(skill)
                tech_score += ((i + 1) * level + len(name) % 7) ** 2 // 4
            scores["technical"] = tech_score
        else:
            scores["technical"] = 15

        # Experience scoring
        experience = candidate.get("experience", [])
        if isinstance(experience, list):
            exp_score = 0
            for i, exp in enumerate(experience[:5]):
                years = exp.get("years", 1) if isinstance(exp, dict) else 1
                level = exp.get("level", 1) if isinstance(exp, dict) else 1
                exp_score += years * (level + 1) * (6 - min(5, i))
            scores["experience"] = exp_score
        else:
            exp_years = int(experience) if isinstance(experience, (int, str)) and str(experience).isdigit() else 2
            scores["experience"] = exp_years * 15

        # Education scoring
        education = candidate.get("education", [])
        if not isinstance(education, list):
            education = [education] if education else []

        edu_score = 0
        degree_values = {"high_school": 10, "associate": 20, "bachelor": 30, "master": 45, "phd": 60}

        for edu in education[:3]:
            if isinstance(edu, dict):
                degree = edu.get("degree", "").lower()
                gpa = edu.get("gpa", 3)
            else:
                degree = "bachelor"
                gpa = 3

            degree_value = degree_values.get(degree, 25)
            edu_score += degree_value + (min(4, int(gpa)) * 5)

        scores["education"] = edu_score if edu_score > 0 else 25

        # Communication scoring
        comm = candidate.get("communication", 3)
        if isinstance(comm, str):
            comm_values = {"poor": 1, "basic": 2, "average": 3, "good": 4, "excellent": 5}
            comm_rating = comm_values.get(comm.lower(), 3)
        else:
            comm_rating = min(5, max(1, int(comm) if isinstance(comm, (int, float)) else 3))

        scores["communication"] = comm_rating ** 2 * 4 + comm_rating * 3

        # Leadership scoring
        leadership = candidate.get("leadership", [])
        if isinstance(leadership, list):
            lead_score = 0
            for i, role in enumerate(leadership[:5]):
                level = role.get("level", 1) if isinstance(role, dict) else 1
                years = role.get("years", 1) if isinstance(role, dict) else 1
                lead_score += level * years * (5 - min(4, i))
        else:
            lead_score = int(leadership) * 8 if isinstance(leadership, (int, float)) else 10

        scores["leadership"] = lead_score

        # Calculate weighted total score
        total_score = sum(scores.get(cat, 0) * skill_weights.get(cat, 1) for cat in skill_weights)

        # Identify strengths and weaknesses
        strengths, weaknesses = [], []
        for category, score in scores.items():
            weight = skill_weights.get(category, 1)
            threshold = 15 * weight
            if score >= threshold * 1.5:
                strengths.append(category)
            elif score <= threshold * 0.6:
                weaknesses.append(category)

        # Store candidate with scores
        name = candidate.get("name", f"Candidate-{idx}")
        scored_candidates.append({
            "name": name, "scores": scores, "total": total_score,
            "strengths": strengths, "weaknesses": weaknesses
        })

    # Sort candidates by total score
    ranked = sorted(scored_candidates, key=lambda x: x["total"], reverse=True)

    # Generate rankings
    for candidate in ranked:
        results["ranked_candidates"].append({
            "name": candidate["name"],
            "score": candidate["total"],
            "strengths": candidate["strengths"],
            "weaknesses": candidate["weaknesses"]
        })

    # Generate recommendations for top 3
    for candidate in ranked[:min(3, len(ranked))]:
        score = candidate["total"]
        if score >= 350:
            recommendation = "Highly Recommend"
        elif score >= 250:
            recommendation = "Recommend"
        elif score >= 150:
            recommendation = "Interview"
        else:
            recommendation = "Reject"

        results["recommendations"].append({
            "name": candidate["name"],
            "decision": recommendation,
            "focus_areas": candidate["weaknesses"]
        })

    # Department matching
    departments = {
        "Engineering": {"technical": 3, "experience": 2, "education": 2},
        "Marketing": {"communication": 3, "experience": 1, "leadership": 2},
        "Sales": {"communication": 3, "leadership": 2, "experience": 1},
        "Product": {"technical": 1, "communication": 2, "leadership": 2},
        "HR": {"communication": 3, "education": 2, "leadership": 1}
    }

    for dept, weights in departments.items():
        best_candidate = None
        best_score = -1

        for candidate in ranked:
            dept_score = sum(candidate["scores"].get(cat, 0) * weight 
                          for cat, weight in weights.items())

            if dept_score > best_score:
                best_score = dept_score
                best_candidate = candidate["name"]

        if best_candidate:
            results["department_matches"][dept] = best_candidate

    return results
```

