import requests

def check_url_status(urls):
    """
    Checks the HTTP status code of a list of URLs and returns a dictionary
    mapping URLs to status codes or error messages.
    """
    results = {}
    for url in urls:
        try:
            response = requests.get(url, timeout=5)
            results[url] = response.status_code
        except requests.exceptions.MissingSchema:
            results[url] = 'Invalid URL: Missing schema (http/https)'
        except requests.exceptions.ConnectionError:
            results[url] = 'Connection error: Could not connect to the URL'
        except requests.exceptions.Timeout:
            results[url] = 'Timeout: The request timed out'
        except requests.exceptions.RequestException as e:
            results[url] = f'An error occurred: {str(e)}'
        except Exception as e:
            results[url] = f'Unexpected error: {str(e)}'
    return results

