def calculate_fibonacci_and_factorial(n):
    """
    Calculates the Fibonacci number at index n and its factorial.
    """
    if n <= 1:
        fib_n = n
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        fib_n = b

    if fib_n == 0:
        factorial_fib = 1
    else:
        factorial_fib = 1
        for i in range(1, fib_n + 1):
            factorial_fib *= i

    return (fib_n, factorial_fib)
