def fibonacci_sequence(n):
    memo = {}
    def fib(k):
        if k in memo:
            return memo[k]
        if k <= 1:
            return k
        memo[k] = fib(k-1) + fib(k-2)
        return memo[k]

    sequence = [fib(i) for i in range(n + 1)]
    return sequence

def sum_even_fibonacci(sequence):
    sum_even = 0
    for num in sequence:
        if num % 2 == 0:
            sum_even += num
    return sum_even

