use warnings;

# Subroutine to sort an array of numbers numerically, maintaining the original order
# of equal elements.
sub orderByNums {
    my ($nums_ref) = @_;  # Receive the array as a reference

    my @nums = @{$nums_ref}; # Dereference the array reference to work with a copy
    my $len = scalar(@nums);  # Determine the length of the array

