        # Inner loop: iterates through the array from the current element of the outer loop
        # up to the last element.
        for (my $j = 0; $j < $len - 1; $j++) {
            # Condition for swapping:
            # 1. If the current element is greater than the next element, OR
            # 2. If the current element is equal to the next element AND the last occurrence
            #    of the current element appears earlier in the original array than the last
            #    occurrence of the next element.  This maintains stability.

