def fibonacci_prime_factors(n):
    fib_sequence = [0, 1]
    while len(fib_sequence) < n:
        next_fib = fib_sequence[-1] + fib_sequence[-2]
        fib_sequence.append(next_fib)

    for num in fib_sequence[:n]:
        factors = []
        if num > 1:
            d = 2
            temp = num
            while d * d <= temp:
                exponent = 0
                while temp % d == 0:
                    exponent += 1
                    temp //= d
                if exponent > 0:
                    factors.append((d, exponent))
                d += 1
            if temp > 1:
                factors.append((temp, 1))
