from typing import Tuple

def get_scope_and_reuse_disc(network_id: int, layer_id: int, num_separate_layers: int) -> Tuple[str, bool]:
    """Determines the scope and a boolean value for a network layer."""
    if network_id == 1:
        if layer_id < num_separate_layers:
            scope = f'd1_encoder_{layer_id}'
            reuse = False
        else:
            scope = f'd_shared_encoder_{layer_id}'
            reuse = False
    else:
        if layer_id < num_separate_layers:
            scope = f'd2_encoder_{layer_id}'
            reuse = False
        else:
            scope = f'd_shared_encoder_{layer_id}'
            reuse = True
    return scope, reuse
```

The function assigns a descriptive identifier and a boolean indicator based on the network and layer numbers. Lower layer numbers within a certain threshold receive a specific designation, while higher ones get a different identifier and a reuse designation of `True` for the second network.

