import json
from datetime import datetime

posts = []
id_counter = 1

def create_post(title, content, author):
    global id_counter
    date = datetime.utcnow().isoformat()
    post = {"id": id_counter, "title": title, "content": content, "author": author, "date": date}
    posts.append(post)
    id_counter += 1
    return post

def read_post(id):
    for post in posts:
        if post["id"] == id:
            return post
    return {}

def read_all_posts():
    return posts

def update_post(id, title, content, author):
    for post in posts:
        if post["id"] == id:
            post["title"] = title
            post["content"] = content
            post["author"] = author
            date = datetime.utcnow().isoformat()
            post["date"] = date
            return post
    return {}

def delete_post(id):
    global posts
    original_length = len(posts)
    posts = [post for post in posts if post["id"] != id]
    return {} if len(posts) == original_length else {}


n = int(input())

for _ in range(n):
    command = input().split()
    if command[0] == "CREATE":
        title = " ".join(command[1:2])
        content = " ".join(command[2:3])
        author = command[3]
        result = create_post(title, content, author)
        print(json.dumps(result))
    elif command[0] == "READALL":
        result = read_all_posts()
        print(json.dumps(result))
    elif command[0] == "READ":
        id = int(command[1])
        result = read_post(id)
        print(json.dumps(result))
    elif command[0] == "UPDATE":
        id = int(command[1])
        title = " ".join(command[2:3])
        content = " ".join(command[3:4])
        author = command[4]
        result = update_post(id, title, content, author)
        print(json.dumps(result))
    elif command[0] == "DELETE":
        id = int(command[1])
        result = delete_post(id)
        print(json.dumps(result))
```

The Python code implements a blog post management system with CRUD operations. It utilizes a list to store posts, each represented as a dictionary. Functions handle creation, retrieval, updating, and deletion based on user commands read from standard input. JSON output is generated using the `json` module.
